/**
* A set of common path utilities commonly used through the Astro core and integration
* projects. These do things like ensure a forward slash prepends paths.
*/
export function appendExtension(path, extension) {
	return path + "." + extension;
}
export function appendForwardSlash(path) {
	return path.endsWith("/") ? path : path + "/";
}
export function prependForwardSlash(path) {
	return path[0] === "/" ? path : "/" + path;
}
export const MANY_LEADING_SLASHES = /^\/{2,}/;
export function collapseDuplicateLeadingSlashes(path) {
	if (!path) {
		return path;
	}
	return path.replace(MANY_LEADING_SLASHES, "/");
}
const MANY_SLASHES = /\/{2,}/g;
export function collapseDuplicateSlashes(path) {
	if (!path) {
		return path;
	}
	return path.replace(MANY_SLASHES, "/");
}
export const MANY_TRAILING_SLASHES = /\/{2,}$/g;
export function collapseDuplicateTrailingSlashes(path, trailingSlash) {
	if (!path) {
		return path;
	}
	return path.replace(MANY_TRAILING_SLASHES, trailingSlash ? "/" : "") || "/";
}
export function removeTrailingForwardSlash(path) {
	return path.endsWith("/") ? path.slice(0, path.length - 1) : path;
}
export function removeLeadingForwardSlash(path) {
	return path.startsWith("/") ? path.substring(1) : path;
}
export function removeLeadingForwardSlashWindows(path) {
	return path.startsWith("/") && path[2] === ":" ? path.substring(1) : path;
}
export function trimSlashes(path) {
	return path.replace(/^\/|\/$/g, "");
}
